/* global window, navigator */
import { useState, useEffect } from "react";
import { isVersionSupported } from "../../functions/utils";

interface DiagnosticInfo {
  isOffline: boolean;
  isOutlookWebApp: boolean;
  isSupportedHost: boolean;
  isVersionSupported: boolean;
  hostVersion: string;
  platform: string;
}

export function useDiagnostics(): DiagnosticInfo {
  const [diagnostics, setDiagnostics] = useState<DiagnosticInfo>({
    isOffline: false,
    isOutlookWebApp: false,
    isSupportedHost: false,
    isVersionSupported: false,
    hostVersion: "",
    platform: "",
  });

  useEffect(() => {
    const getDiagnostics = async () => {
      try {
        if (!Office.context.diagnostics) return;
        // Check if we're offline
        const isOffline = !navigator.onLine;

        // Check if we're in Outlook Web App
        const isOutlookWebApp = Office.context.platform === Office.PlatformType.OfficeOnline;

        // Get host info
        const hostVersion = Office.context.diagnostics.version;
        const platform = Office.context.diagnostics.platform as unknown as string;
        const host = Office.context.host as unknown as string;

        // Check if we're in a supported host
        const isSupportedHost = Office.context.host === Office.HostType.Excel;

        setDiagnostics({
          isOffline,
          isOutlookWebApp,
          isSupportedHost,
          isVersionSupported: isVersionSupported(host, platform, hostVersion),
          hostVersion,
          platform,
        });
      } catch (error) {
        console.error("Error getting diagnostics:", error);
      }
    };

    getDiagnostics();

    // Listen for online/offline events
    window.addEventListener("online", () => setDiagnostics((prev) => ({ ...prev, isOffline: false })));
    window.addEventListener("offline", () => setDiagnostics((prev) => ({ ...prev, isOffline: true })));

    return () => {
      window.removeEventListener("online", () => setDiagnostics((prev) => ({ ...prev, isOffline: false })));
      window.removeEventListener("offline", () => setDiagnostics((prev) => ({ ...prev, isOffline: true })));
    };
  }, []);

  return diagnostics;
}
