import React, { useEffect } from "react";
import { useNavigate } from "react-router-dom";
import { getFromLocalStorage } from "../../taskpane";
import TemplateGenerator from "../TemplateGeneratorPage/TemplateGenerator";

const TemplateGeneratorPage: React.FC = () => {
  const navigate = useNavigate();

  useEffect(() => {
    const localApiKey = getFromLocalStorage("apiKey");
    if (!localApiKey) {
      navigate("/onboarding");
    }
  }, []);

  return (
    <div className="relative">
      <TemplateGenerator />
    </div>
  );
};

export default TemplateGeneratorPage;
