import React, { useState } from "react";
import { AzureOpenAI } from "openai";
import { getAllSheetName, getSheetValuesWithAddress, setSheetValues } from "./toolUse";
import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

import { sheetNameConsideration, schemaConsideration, tableGeneration } from "./prompts";

const TemplateGenerator: React.FC = () => {
  const [query, setQuery] = useState("AAPL DCF");
  const [loading, setLoading] = useState(false);
  const [openaiKey, setOpenaiKey] = useState("");
  const [groqKey, setGroqKey] = useState("");
  const [r1ApiKey, setR1ApiKey] = useState("");
  const [model, setModel] = useState<"openai" | "groq" | "deepseek">("openai");
  const [openaiUrl, setOpenaiUrl] = useState("");
  const [response, setResponse] = useState("");

  const [prompt1, setPrompt1] = useState(sheetNameConsideration);
  const [prompt2, setPrompt2] = useState(schemaConsideration);
  const [prompt3, setPrompt3] = useState(tableGeneration);

  const handleSubmit2 = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    setResponse("");
    const openai = new AzureOpenAI({
      endpoint: openaiUrl,
      deployment: "gpt4o-mini-deployment",
      apiKey: openaiKey,
      apiVersion: "2024-05-01-preview",
      dangerouslyAllowBrowser: true,
    });
    const structureResponse = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      messages: [
        {
          role: "system",
          content: prompt1,
        },
        {
          role: "user",
          content: query,
        },
      ],
      max_tokens: 2000,
      temperature: 0.7,
      n: 1,
      stream: true,
    });

    let structureResponseStr = "";
    setResponse((prev) => prev + `\n---\n`);
    for await (const chunk of structureResponse) {
      setResponse((prev) => prev + (chunk.choices[0]?.delta?.content || ""));
      structureResponseStr += chunk.choices[0]?.delta?.content || "";
    }

    const schemaResponse = await openai.chat.completions.create({
      model: "gpt-4o-mini",
      response_format: { type: "json_object" },
      messages: [
        {
          role: "system",
          content: prompt2.replace("{{date}}", new Date().toISOString()),
        },
        {
          role: "assistant",
          content: structureResponseStr,
        },
        {
          role: "user",
          content: query,
        },
      ],
    });

    console.log("schemaResponse", schemaResponse.choices[0].message.content);

    const sheetConfigs = JSON.parse(schemaResponse.choices[0].message.content);
    console.log("sheetConfigs", sheetConfigs);

    for await (const sheet of sheetConfigs.sheets) {
      console.log(sheet);

      const generateResponse = openai.beta.chat.completions.runTools({
        model: "gpt-4o-mini",
        messages: [
          {
            role: "system",
            content: prompt3.replace("{{date}}", new Date().toISOString()),
          },
          {
            role: "user",
            content: `
              Query: {{query}}
      sheetConfig: {{sheetConfig}}`
              .replace("{{query}}", query)
              .replace("{{sheetConfig}}", JSON.stringify(sheet))
              .replace("{{date}}", new Date().toISOString()),
          },
        ],
        max_tokens: 10000,
        temperature: 0.7,
        n: 1,
        stream: true,
        tools: [
          {
            type: "function",
            function: {
              function: getAllSheetName,
              parse: JSON.parse,
              description: "Get all sheet names",
              parameters: {},
            },
          },
          {
            type: "function",
            function: {
              function: getSheetValuesWithAddress,
              parse: JSON.parse,
              description: "Get values for a sheet with address",
              parameters: { type: "object", properties: { sheetName: { type: "string" } } },
            },
          },
          {
            type: "function",
            function: {
              function: setSheetValues,
              parse: JSON.parse,
              description: "Set values for a sheet starting from A1",
              parameters: {
                type: "object",
                properties: {
                  sheetName: { type: "string" },
                  startAtRange: { type: "string" },
                  values: { type: "array", items: { type: "array", items: { type: "string" } } },
                },
              },
            },
          },
        ],
      });

      let responseStr = "";
      setResponse((prev) => prev + `\n---\n`);
      setResponse((prev) => prev + `\n- Generating sheet values...${sheet.sheetName}`);
      for await (const chunk of generateResponse) {
        setResponse((prev) => prev + (chunk.choices[0]?.delta?.content || ""));
        responseStr += chunk.choices[0]?.delta?.content || "";
      }
      setResponse((prev) => prev + `\n- Generating sheet values...${sheet.sheetName} ✅`);
      console.log("responseStr", responseStr);
    }

    return;
  };

  return (
    <div className="p-4">
      <h3 className="text-lg font-semibold mb-4">Template Generator</h3>
      <h4 className="text-lg font-semibold mb-4">Openai API URL</h4>
      <input
        type="text"
        className="w-full p-2 border border-gray-300 rounded-md mb-4"
        value={openaiUrl}
        onChange={(e) => setOpenaiUrl(e.target.value)}
        placeholder="Enter API URL"
      />
      <h4 className="text-lg font-semibold mb-4">Openai API Key</h4>
      <input
        type="text"
        className="w-full p-2 border border-grafy-300 rounded-md mb-4"
        value={openaiKey}
        onChange={(e) => setOpenaiKey(e.target.value)}
        placeholder="Enter your Openai API key"
      />

      <h4 className="text-lg font-semibold mb-4">Groq Key</h4>
      <input
        type="text"
        className="w-full p-2 border border-gray-300 rounded-md mb-4"
        value={groqKey}
        onChange={(e) => setGroqKey(e.target.value)}
        placeholder="Enter your Groq key"
      />

      <textarea
        className="w-full p-2 border border-gray-300 rounded-md mb-4 text-[8px]"
        rows={4}
        value={prompt1}
        onChange={(e) => setPrompt1(e.target.value)}
        placeholder="Enter your prompt1"
      />

      <textarea
        className="w-full p-2 border border-gray-300 rounded-md mb-4 text-[8px]"
        rows={4}
        value={prompt2}
        onChange={(e) => setPrompt2(e.target.value)}
        placeholder="Enter your prompt2"
      />

      <textarea
        className="w-full p-2 border border-gray-300 rounded-md mb-4 text-[8px]"
        rows={4}
        value={prompt3}
        onChange={(e) => setPrompt3(e.target.value)}
        placeholder="Enter your prompt3"
      />

      <textarea
        className="w-full p-2 border border-gray-300 rounded-md mb-4"
        rows={4}
        value={query}
        onChange={(e) => setQuery(e.target.value)}
        placeholder="Enter your query to generate a template..."
      />

      {/* <button
        disabled={loading}
        onClick={handleSubmit}
        className="w-full rounded-lg bg-darker px-6 py-3 text-white flex flex-row gap-2 w-full text-center justify-center items-center hover:shadow-button disabled:bg-grey disabled:text-darkGrey"
      >
        {loading ? "Generating..." : "Generate Template"}
      </button> */}

      <button
        disabled={loading}
        onClick={handleSubmit2}
        className="w-full rounded-lg bg-darker px-6 py-3 text-white flex flex-row gap-2 w-full text-center justify-center items-center hover:shadow-button disabled:bg-grey disabled:text-darkGrey"
      >
        {loading ? "Generating..." : "Generate Template2"}
      </button>

      <div className="w-full p-2 border border-gray-300 rounded-md mb-4">
        <h4 className="text-lg font-semibold mb-4">Response</h4>
        <ReactMarkdown className="text-sm markdown" remarkPlugins={[remarkGfm]}>
          {response}
        </ReactMarkdown>
      </div>
    </div>
  );
};

export default TemplateGenerator;
