/* global document, Node, MouseEvent, setTimeout */
import React, { useCallback, useState } from "react";
import { calculateCells, delay, storeValues } from "../../utils";
import classNames from "classnames";
import ContentEditable from "react-contenteditable";
import { useHelperSections } from "../../hooks/useHelperSections";
import FormulaInUsed from "./FormulaInUsed";
import { IconEraser, IconLoader2 } from "@tabler/icons-react";

const HelperSelection = () => {
  const { value, isListening, onListen, onUnlisten, onInputChange, setValue } = useHelperSections();
  const textareaRef = React.useRef(null);
  const [isStoreAsValueLoading, setIsStoreAsValueLoading] = useState(false);
  const [isRegenerateLoading, setIsRegenerateLoading] = useState(false);

  React.useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (!textareaRef.current?.contains(event.target as Node)) {
        onUnlisten();
      }
    };

    document.addEventListener("mousedown", handleClickOutside);

    return () => {
      document.removeEventListener("mousedown", handleClickOutside);
    };
  }, [textareaRef, onUnlisten, onListen]);

  const onStoreAsValue = async () => {
    try {
      setIsStoreAsValueLoading(true);
      onUnlisten();
      const ranges = value
        .split(",")
        .map((v) => v.trim())
        .filter((v) => v.length > 0)
        .filter((v) => /^[A-Z]+[0-9]+:[A-Z]+[0-9]+$|^[A-Z]+[0-9]+$/.test(v));

      await storeValues(ranges);
    } catch (error) {
      console.error(error);
    } finally {
      await delay(500);
      setIsStoreAsValueLoading(false);
    }
  };

  const regenerate = async () => {
    try {
      setIsRegenerateLoading(true);
      onUnlisten();
      const ranges = value
        .split(",")
        .map((v) => v.trim())
        .filter((v) => v.length > 0)
        .filter((v) => /^[A-Z]+[0-9]+:[A-Z]+[0-9]+$|^[A-Z]+[0-9]+$/.test(v));
      await calculateCells(ranges);
    } catch (error) {
      console.error(error);
    } finally {
      await delay(500);
      setIsRegenerateLoading(false);
    }
  };

  const onValueClickHandler = useCallback(
    (value: string) => {
      setValue(value);
      onUnlisten();
    },
    [setValue, onUnlisten]
  );

  const onErase = () => {
    onUnlisten();
    setValue("");
  };

  return (
    <>
      <FormulaInUsed onValueClick={onValueClickHandler} />
      <div className="p-3 py-1 flex flex-col gap-2 mb-3">
        <div className="relative">
          <ContentEditable
            className={classNames(
              "cursor-text border border-lightGrey rounded px-2.5 py-3 text-xs min-h-[104px] overflow-y-auto text-orange pb-8 max-h-[400px]",
              {
                "outline outline-purple outline-2": isListening,
              }
            )}
            innerRef={textareaRef}
            contentEditable="plaintext-only"
            onChange={onInputChange}
            onFocus={onListen}
            html={value.replace(/\n/g, "<br>")}
          ></ContentEditable>
          <button
            onClick={onErase}
            className="p-1 absolute bottom-2 right-2 bg-lightGrey cursor-pointer hover:bg-lightGrey/80 rounded"
          >
            <IconEraser size={16} />
          </button>
        </div>
        <div className="flex flex-row justify-between items-center gap-2">
          <button
            className={classNames(
              "bg-lightGrey rounded p-1 px-2.5 text-xs flex-1 text-center p-2",
              "hover:bg-dark hover:text-white",
              {
                "disabled:opacity-50": !isStoreAsValueLoading,
                "pointer-events-none": isStoreAsValueLoading,
              }
            )}
            onClick={onStoreAsValue}
            disabled={!value || isStoreAsValueLoading}
          >
            {isStoreAsValueLoading ? <IconLoader2 size={12} className="animate-spin inline" /> : "Store as Value"}
          </button>
          <button
            className={classNames(
              "bg-lightGrey rounded p-1 px-2.5 text-xs flex-1 text-center p-2",
              "hover:bg-darker hover:text-white",
              {
                "disabled:opacity-50": !isRegenerateLoading,
                "pointer-events-none": isRegenerateLoading,
              }
            )}
            onClick={regenerate}
            disabled={!value || isRegenerateLoading}
          >
            {isRegenerateLoading ? <IconLoader2 size={12} className="animate-spin inline" /> : "Regenerate"}
          </button>
        </div>
      </div>
    </>
  );
};

export default HelperSelection;
