/* global document */
import React, { useState, useCallback, useMemo } from "react";
import { IconChevronDown, IconChevronUp, IconCopy } from "@tabler/icons-react";
import { Formula } from "./Instructions";

function unsecuredCopyToClipboard(text: string) {
  const textArea = document.createElement("textarea");
  textArea.value = text;
  document.body.appendChild(textArea);
  //   textArea.focus();
  textArea.select();
  try {
    document.execCommand("copy");
  } catch (err) {
    console.error("Unable to copy to clipboard", err);
  }
  document.body.removeChild(textArea);
}

interface FormulaExampleProps {
  formula: Formula;
}

export const FormulaExample = ({ formula }: FormulaExampleProps) => {
  const [collapsed, setCollapsed] = useState(true);
  const onCopy = useCallback(() => {
    unsecuredCopyToClipboard(formula.exampleText);
  }, [formula.exampleText]);
  const example = useMemo(() => formula.example(), [formula.name]);

  return (
    <div className="rounded border border-lightGrey p-2.5 w-full hover:bg-lightGrey/10">
      <button
        className="text-sm flex flex-row justify-between items-center w-full cursor-pointer"
        onClick={() => setCollapsed(!collapsed)}
      >
        <span className="font-sm font-title tracking-title font-medium">{formula.name}</span>
        {collapsed ? <IconChevronDown size={16} /> : <IconChevronUp size={16} />}
      </button>
      {!collapsed && (
        <>
          <div className="text-xs mt-3">{formula.description}</div>
          <div className="p-3 bg-lightGrey rounded mt-2">
            <div className="flex flex-row justify-between items-center mb-3">
              <p className="text-xs font-title tracking-title">Example</p>
              <button className="text-xs text-darkGrey hover:text-darkGrey/80 cursor-pointer" onClick={onCopy}>
                <IconCopy size={16} />
              </button>
            </div>
            <div>{example}</div>
          </div>
        </>
      )}
    </div>
  );
};
