import React, { useState } from "react";
import { UseFormRegister } from "react-hook-form";
import { IconEye, IconEyeOff } from "@tabler/icons-react";

interface TokenInputProps {
  id: string;
  label?: string;
  register: UseFormRegister<any>;
  placeholder?: string;
  className?: string;
}

export const TokenInput: React.FC<TokenInputProps> = ({ id, label, register, placeholder, className }) => {
  const [showToken, setShowToken] = useState(false);

  return (
    <div className="">
      {label && (
        <label htmlFor={id} className="items-center font-title text-sm mb-2">
          {label}
        </label>
      )}
      <div className="relative">
        <div className="w-full rounded border border-lightGrey">
          <input
            className={`placeholder-color-lightGrey w-full font-sm p-3 py-2 pr-14 ${className} my-[1px]`}
            type={showToken ? "text" : "password"}
            id={id}
            {...register(id)}
            placeholder={placeholder}
          />
        </div>
        <button
          type="button"
          className="text-xs absolute right-3 top-1/2 -translate-y-1/2 text-royalBlue hover:text-royalBlue/80"
          onClick={() => setShowToken(!showToken)}
        >
          {showToken ? <IconEyeOff color="#A729F6" size={16} /> : <IconEye color="#A729F6" size={16} />}
        </button>
      </div>
    </div>
  );
};
