/* global window */
import { useCallback, useEffect, useState } from "react";

export const useHelperSections = () => {
  const [oldValue, setOldValue] = useState("");
  const [valueSheetId, setValueSheetId] = useState("");
  const [sheetId, setSheetId] = useState("");
  const [value, setValue] = useState("");
  const [isListening, setIsListening] = useState(false);
  const [, setHandlerRemove] = useState<any[]>([]);

  const onListen = useCallback(async () => {
    if (isListening) return;
    setIsListening(true);
    await Excel.run({ delayForCellEdit: true }, async (context) => {
      const sheet = context.workbook.worksheets.getActiveWorksheet();
      sheet.load("id");
      await context.sync();
      setSheetId(sheet.id);
    });
  }, [isListening, setIsListening]);

  const onUnlisten = useCallback(() => {
    setIsListening(false);
  }, [setIsListening, setValue, setOldValue]);

  const setValueHandler = useCallback(
    (value: string) => {
      setValue(value);
      setOldValue(value.trim());
    },
    [setValue, setOldValue]
  );

  const onRangeSelectionChanged = useCallback(
    async (args) => {
      if (args.type !== Excel.EventType.worksheetSelectionChanged) return;
      console.log("onRangeSelectionChanged", isListening, args);
      const address = args.address;
      setValueSheetId(args.sheetId);
      if (!oldValue) {
        setValue(address);
      } else {
        setValue(oldValue.trimEnd().replace(/,$/, "") + "," + address);
      }
    },
    [isListening, oldValue, setValue]
  );

  useEffect(() => {
    if (!isListening) {
      setValue((prev) => {
        const trimmed = prev
          .split(",")
          .map((v) => v.trim())
          .filter((v) => v.length > 0)
          .filter((v) => /^[A-Z]+[0-9]+:[A-Z]+[0-9]+$|^[A-Z]+[0-9]+$/.test(v))
          .join(", ");
        setOldValue(trimmed);
        return trimmed;
      });
      setHandlerRemove((prev) => {
        if (prev) prev.forEach((p) => p.remove());
        return [];
      });
    }
  }, [isListening, setHandlerRemove, setValue, setOldValue]);

  useEffect(() => {
    if (!window.Office || !window.Excel) return () => {};

    Excel.run({ delayForCellEdit: true }, async (context) => {
      if (!isListening) return;
      const handler = context.workbook.worksheets.onSelectionChanged.add(onRangeSelectionChanged);
      setHandlerRemove((prev) => {
        return [...prev, handler];
      });
      await context.sync();
    }).catch((error) => {
      console.error(error);
    });

    return () => {
      setHandlerRemove((prev) => {
        if (prev)
          prev.forEach((p) => {
            p.remove();
            p.context.sync();
          });
        return [];
      });
    };
  }, [onRangeSelectionChanged, setHandlerRemove, isListening]);

  useEffect(() => {
    if (!window.Office || !window.Excel) {
      return () => {};
    }
    const onDocumentSelectChange = async () => {
      Excel.run({ delayForCellEdit: true }, async (context) => {
        const sheet = context.workbook.worksheets.getActiveWorksheet();
        sheet.load("id");
        await context.sync();
        setSheetId(sheet.id);
      }).catch((error) => {
        console.error(error);
      });
    };
    Office.context.document.addHandlerAsync(Office.EventType.DocumentSelectionChanged, onDocumentSelectChange);
    return () => {
      Office.context.document.removeHandlerAsync(Office.EventType.DocumentSelectionChanged, onDocumentSelectChange);
    };
  }, []);

  useEffect(() => {
    if (sheetId !== valueSheetId) {
      onUnlisten();
      setValue("");
      setOldValue("");
      setValueSheetId(sheetId);
    }
  }, [sheetId]);

  const onInputChange = useCallback(
    (e) => {
      const value = e.target.value
        .replace(/<br>/g, "\n")
        .replace(/<div>/g, "\n")
        .replace(/<\/div>/g, "");
      console.log({ e });
      setValueHandler(value);
    },
    [setValueHandler]
  );

  return {
    value,
    isListening,
    onListen,
    onUnlisten,
    onInputChange,
    setValue: setValueHandler,
  };
};
