import { toAddress } from "../../utils";

export async function getAllSheetName() {
  console.log("getAllSheetName");
  return Excel.run(async (context) => {
    const workbook = context.workbook;
    workbook.worksheets.load("items");
    await context.sync();
    const sheetNames = workbook.worksheets.items.map((sheet) => sheet.name);
    return sheetNames;
  }).catch((error) => {
    console.error(error);
    return [];
  });
}

export async function removeAllSheet() {
  console.log("removeAllSheet");
  return Excel.run(async (context) => {
    context.workbook.worksheets.items.forEach((sheet) => sheet.delete());
    await context.sync();
    return { success: true };
  });
}

export async function createSheet(args: { sheetNames: string[] }) {
  console.log("createSheet", args);
  return Excel.run(async (context) => {
    args.sheetNames.forEach((sheetName) => {
      context.workbook.worksheets.add(sheetName);
    });
    await context.sync();
    return { success: true };
  }).catch((error) => {
    console.error(error);
    return { success: false, error: error.message };
  });
}

export async function setSheetValues(args: { sheetName: string; startAtRange: string; values: any[][] }) {
  console.log("setSheetValues", args);

  const maxRow = args.values.reduce((max, row) => Math.max(max, row.length), 0);
  args.values.forEach((row) => {
    if (row.length < maxRow) {
      row.push(...Array(maxRow - row.length).fill(""));
    }
  });

  return Excel.run(async (context) => {
    console.log("getItemOrNullObject", args.sheetName);
    let sheet = context.workbook.worksheets.getItemOrNullObject(args.sheetName);
    console.log("await context.sync();");
    await context.sync();
    console.log("sheet.isNullObject");
    if (sheet.isNullObject) {
      sheet = context.workbook.worksheets.add(args.sheetName);
      await context.sync();
    }
    console.log("startAtRange");

    const startAtRange = args.startAtRange.split(":")[0];
    console.log("startAtRange", startAtRange);
    const startRange = sheet.getRange(startAtRange);
    console.log("startRange");
    const range = startRange.getResizedRange(args.values.length - 1, args.values[0].length - 1);
    console.log("range");
    range.values = args.values;
    console.log("range.values");
    // range.calculate();
    range.format.autofitColumns();
    console.log("range.format.autofitColumns");
    range.format.autofitRows();
    console.log("range.format.autofitRows");
    range.load("address");
    console.log("range.load");
    await context.sync();
    console.log("await context.sync();");
    return { success: true, range: range.address.split("!")[1] };
  }).catch((error) => {
    console.error(error);
    return { success: false, error: error.message };
  });
}

export async function setNewTableToSheet(args: { sheetName: string; values: any[][] }) {
  console.log("setNewTableToSheet", args);
  return Excel.run(async (context) => {
    let sheet = context.workbook.worksheets.getItemOrNullObject(args.sheetName);
    await context.sync();
    if (sheet.isNullObject) {
      sheet = context.workbook.worksheets.add(args.sheetName);
      await context.sync();
    }
    const usedRange = sheet.getUsedRangeOrNullObject();

    await context.sync();
    let startRow = 0;
    if (!usedRange.isNullObject) {
      usedRange.load("rowCount");
      await context.sync();
      startRow = usedRange.rowCount + 1;
    }

    const maxRow = args.values.reduce((max, row) => Math.max(max, row.length), 0);
    args.values.forEach((row) => {
      if (row.length < maxRow) {
        row.push(...Array(maxRow - row.length).fill(""));
      }
    });

    const range = sheet.getRangeByIndexes(startRow, 0, args.values.length, args.values[0].length);
    range.values = args.values;
    range.format.autofitColumns();
    range.format.autofitRows();
    await context.sync();
    return { success: true };
  });
}

async function freezePanes(args: { sheetName: string; numberOfColumnsToFreeze: number; numberOfRowsToFreeze: number }) {
  console.log("freezePanes", args);
  return Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getItem(args.sheetName);
    sheet.freezePanes.freezeColumns(args.numberOfColumnsToFreeze);
    sheet.freezePanes.freezeRows(args.numberOfRowsToFreeze);
    await context.sync();
    return { success: true };
  }).catch((error) => {
    console.error(error);
    return { success: false, error: error.message };
  });
}

async function getSheetValues(args: { sheetName: string }) {
  console.log("getSheetValues", args);
  return Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getItem(args.sheetName);
    await context.sync();
    const range = sheet.getUsedRange();
    range.load("values");
    await context.sync();
    return { success: true, values: range.values };
  }).catch((error) => {
    console.error(error);
    return { success: false, error: error.message };
  });
}

export async function getSheetValuesWithAddress(args: { sheetName: string }) {
  console.log("getSheetValuesWithAddress", args);
  return Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getItemOrNullObject(args.sheetName);
    await context.sync();
    if (sheet.isNullObject) {
      return { success: false, error: "Sheet not found" };
    }
    const range = sheet.getUsedRange();
    range.load("formulas");
    await context.sync();
    return {
      success: true,
      values: range.formulas.map((row, rowIndex) =>
        row.map((cell, columnIndex) => ({
          value: cell,
          address: toAddress("A1", rowIndex, columnIndex),
        }))
      ),
    };
  }).catch((error) => {
    console.error(error);
    return { success: false, error: error.message };
  });
}

