export const createChart = async (args: {
  sheetName: string;
  dataRangeString: string;
  chartType: Excel.ChartType;
  chartTitle: string;
  chartDescription: string;
  chartLegendPosition: Excel.ChartLegendPosition;
  chartBackgroundColor: string;
  chartFontColor: string;
  chartFontSize: number;
}) => {
  console.log("createChart", args);
  return Excel.run(async (context) => {
    const sheet = context.workbook.worksheets.getItem(args.sheetName);
    let dataRange = sheet.getRange(args.dataRangeString);
    let chart = sheet.charts.add(args.chartType as Excel.ChartType, dataRange, Excel.ChartSeriesBy.auto);
    chart.title.text = args.chartTitle;
    chart.legend.position = args.chartLegendPosition as Excel.ChartLegendPosition;
    chart.legend.format.fill.setSolidColor(args.chartBackgroundColor);
    chart.dataLabels.format.font.size = Number(args.chartFontSize);
    chart.dataLabels.format.font.color = args.chartFontColor;
    await context.sync();
    return { success: true };
  }).catch((error) => {
    console.error(error);
    return { success: false, error: error.message };
  });
};