import React from "react";
import { IconAlertCircleFilled, IconX } from "@tabler/icons-react";
import classNames from "classnames";

interface AlertProps {
  error: string;
  children?: React.ReactNode;
  hide?: boolean;
  onClose?: () => void;
}

const Alert: React.FC<AlertProps> = ({ error, children, hide, onClose }) => {
  if (hide) return null;
  return (
    <>
      <div
        className={classNames(
          "fixed transition-transform duration-200 bottom-0 left-0 right-0 w-full border-t bg-lightOrange border-orange p-3 z-10",
          {
            "translate-y-full": !error,
            "translate-y-0": error,
          }
        )}
      >
        <div className="flex flex-row items-center justify-between">
          <div className={classNames("flex items-center gap-2 flex-start flex-row")}>
            <IconAlertCircleFilled size={24} className="text-orange" />
            <div>
              <span className="font-title text-sm">{error}</span>
            </div>
          </div>
          {onClose && <IconX size={16} className="cursor-pointer se" onClick={onClose} />}
        </div>
        {children && (
          <div className="flex flex-row items-center flex-start gap-2">
            <div className="w-[24px]" />
            <div className="pl-2 pt-2">{children}</div>
          </div>
        )}
      </div>
    </>
  );
};

export default Alert;
