import React, { useMemo, useState } from "react";
import useConsoleStore from "../../stores/console";

const CollapsibleLogObject = ({ arg }: { arg: any }) => {
  const [isOpen, setIsOpen] = useState(false);
  if (!arg) return <div>{`${arg}`}</div>;
  return (
    <div>
      <button onClick={() => setIsOpen(!isOpen)}>{isOpen ? "close" : "open"}</button>
      {isOpen ? <div className="whitespace-pre-wrap">{JSON.stringify(arg)}</div> : null}
    </div>
  );
};

interface RequestDebugProps {
  id: string;
  type: string;
  address: string;
  ticker?: string;
  query?: string;
  options?: any;
  entity?: any;
  error?: any;
  response: any;
  start: string;
  end: string;
}

const RequestDebug = () => {
  const { logs } = useConsoleStore();
  const requests: Array<RequestDebugProps> = useMemo(
    () =>
      logs
        .filter((log) => log.args?.[0]?.logType === "request")
        .map((log) => log.args[0] as unknown as RequestDebugProps)
        .reverse(),
    [logs]
  );

  return (
    <div className="bg-white border rounded shadow-sm overflow-x-auto">
      <table className="min-w-full divide-y divide-gray-200">
        <thead className="bg-gray-50">
          <tr>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              type
            </th>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              start
            </th>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              ms
            </th>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              ticker
            </th>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              query
            </th>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              Response
            </th>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              Entity
            </th>
            <th scope="col" className="p-2 text-left text-[8px] font-medium text-gray-500 uppercase tracking-wider">
              Options
            </th>
          </tr>
        </thead>
        <tbody className="bg-white divide-y divide-gray-200">
          {requests.map((request) => (
            <tr key={request.id}>
              <td className={`p-2 whitespace-nowrap text-[8px] ${request.error ? "text-red" : "text-green"}`}>
                {request.type}
              </td>
              <td className="p-2 whitespace-nowrap text-[8px] text-gray-500">
                {new Date(request?.start).toTimeString().slice(0, 8)}
              </td>
              <td className="p-2 whitespace-nowrap text-[8px] text-gray-500">
                {new Date(request?.end).getTime() - new Date(request?.start).getTime()}ms
              </td>
              <td className="p-2 whitespace-nowrap text-[8px] text-gray-500">{request.ticker || "-"}</td>
              <td className="p-2 text-[8px] text-gray-500">{request.query || "-"}</td>
              <td className="p-2 whitespace-nowrap text-[8px] text-gray-500">
                <CollapsibleLogObject arg={request.response || request.error} />
              </td>
              <td className="p-2 whitespace-nowrap text-[8px] text-gray-500">
                <CollapsibleLogObject arg={request.entity} />
              </td>
              <td className="p-2 whitespace-nowrap text-[8px] text-gray-500">
                <CollapsibleLogObject arg={request.options} />
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
};

export default RequestDebug;
